<?php
require __DIR__.'/authentication/guard.php';
date_default_timezone_set('Asia/Manila');
$db = prototypeDb();
$db->exec('PRAGMA foreign_keys=ON');
$db->exec("CREATE TABLE IF NOT EXISTS records (id INTEGER PRIMARY KEY, kind TEXT NOT NULL, data TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP, updated_at TEXT DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS events (id INTEGER PRIMARY KEY, record_id INTEGER NOT NULL REFERENCES records(id), type TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);");
$columns=$db->query("PRAGMA table_info(records)")->fetchAll(PDO::FETCH_ASSOC);
if(!in_array('deleted_at',array_column($columns,'name'),true)) $db->exec('ALTER TABLE records ADD COLUMN deleted_at TEXT');
$fields = [
'assets'=>['asset_id'=>'Asset ID','serial'=>'Serial number','name'=>'Item name','category'=>'Category','brand'=>'Brand','model'=>'Model','specifications'=>'Specifications','employee'=>'Employee','department'=>'Department','site'=>'Site','room'=>'Room','status'=>'Status','condition'=>'Condition','purchase_cost'=>'Purchase cost','supplier'=>'Supplier','invoice'=>'Invoice / PO','warranty'=>'Warranty expiry','notes'=>'Notes'],
'supplies'=>['sku'=>'Item ID / SKU','name'=>'Item name','category'=>'Category','location'=>'Location','quantity'=>'Quantity on hand','reorder'=>'Reorder level','supplier'=>'Supplier','unit_cost'=>'Unit cost','notes'=>'Notes'],
'licenses'=>['name'=>'License / subscription','provider'=>'Provider','location'=>'Location / site','seats'=>'Total seats','assigned'=>'Assigned seats','assignments'=>'Assignments','cost'=>'Cost','frequency'=>'Billing frequency','renewal'=>'Renewal date','expiry'=>'Expiry date','documents'=>'Document reference','notes'=>'Notes']];
$kind = $_GET['page'] ?? 'dashboard'; if (!in_array($kind, ['dashboard','assets','supplies','licenses'], true)) $kind='dashboard';
function h($v){return htmlspecialchars((string)($v ?? ''), ENT_QUOTES, 'UTF-8');}
function data($r){return array_merge(['location'=>''], json_decode($r['data'],true) ?: []);}
function all($db,$kind){$s=$db->prepare('SELECT * FROM records WHERE kind=? AND deleted_at IS NULL ORDER BY id DESC');$s->execute([$kind]);return $s->fetchAll(PDO::FETCH_ASSOC);}
function money($n){return number_format((float)$n,2);}
if (empty($_SESSION['csrf'])) $_SESSION['csrf']=bin2hex(random_bytes(32));
$error='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
 try {
  if (!hash_equals($_SESSION['csrf'], $_POST['csrf'] ?? '')) throw new Exception('Your session expired. Refresh and try again.');
  $k=$_POST['kind'] ?? ''; if (!isset($fields[$k])) throw new Exception('Invalid register.');
  $id=(int)($_POST['id'] ?? 0); $action=$_POST['action'] ?? 'save';if(in_array($action,['delete','restore'],true) && $user['role']!=='superadmin')throw new Exception('Super administrator access required.');
  if ($id) { $s=$db->prepare($action==='restore'?'SELECT * FROM records WHERE id=? AND kind=? AND deleted_at IS NOT NULL':'SELECT * FROM records WHERE id=? AND kind=? AND deleted_at IS NULL');$s->execute([$id,$k]);$record=$s->fetch(PDO::FETCH_ASSOC);if(!$record) throw new Exception('Record not found.'); }
  if ($action==='delete') { if(!$id) throw new Exception('Record not found.'); $db->beginTransaction(); $s=$db->prepare('UPDATE records SET deleted_at=CURRENT_TIMESTAMP WHERE id=?'); $s->execute([$id]); $s=$db->prepare('INSERT INTO events(record_id,type,detail) VALUES(?,?,?)'); $s->execute([$id,'Deleted','Local user moved this record to deleted records.']); $db->commit(); $_SESSION['flash']='Record deleted and retained in deleted records.'; header('Location: ?page='.$k); exit; } elseif ($action==='restore') { if(!$id) throw new Exception('Record not found.'); $restored=data($record);$identifier=$k==='assets'?'asset_id':($k==='supplies'?'sku':null);if($identifier) foreach(all($db,$k) as $existing){$ed=data($existing);if(strcasecmp($ed[$identifier]??'', $restored[$identifier]??'')===0 && ($k!=='supplies' || strcasecmp($ed['location']??'', $restored['location']??'')===0)) throw new Exception('Cannot restore: an active record already uses this ID'.($k==='supplies'?' at this location.':'.'));} $db->beginTransaction();$s=$db->prepare('UPDATE records SET deleted_at=NULL WHERE id=?');$s->execute([$id]);$s=$db->prepare('INSERT INTO events(record_id,type,detail) VALUES(?,?,?)');$s->execute([$id,'Restored','Local user restored this record.']);$db->commit();$_SESSION['flash']='Record restored successfully.';header('Location: ?page='.$k.'&view='.$id);exit; } elseif ($action==='save') {
   $d=[];foreach($fields[$k] as $key=>$label) $d[$key]=trim((string)($_POST[$key] ?? ''));
   $required=$k==='assets'?['asset_id','name']:($k==='supplies'?['sku','name','location']:['name','provider']);
   foreach($required as $key) if($d[$key]==='') throw new Exception($fields[$k][$key].' is required.');
   foreach (['quantity','reorder','unit_cost','purchase_cost','seats','assigned','cost'] as $key) if(isset($d[$key]) && $d[$key]!=='' && (!is_numeric($d[$key]) || (float)$d[$key]<0)) throw new Exception($fields[$k][$key].' must be a non-negative number.');
   if($k==='licenses' && $d['assigned']!=='' && $d['seats']!=='' && (int)$d['assigned']>(int)$d['seats']) throw new Exception('Assigned seats cannot exceed total seats.');
   $identifier=$k==='assets'?'asset_id':($k==='supplies'?'sku':null);
   if($identifier) foreach(all($db,$k) as $existing){$ed=data($existing);if((int)$existing['id']!==$id && strcasecmp($ed[$identifier] ?? '',$d[$identifier])===0 && ($k!=='supplies' || strcasecmp($ed['location'] ?? '',$d['location'])===0)) throw new Exception('That ID already exists'.($k==='supplies'?' at this location.':'.'));}
   $json=json_encode($d, JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);
   if($id){$s=$db->prepare('UPDATE records SET data=?,updated_at=CURRENT_TIMESTAMP WHERE id=?');$s->execute([$json,$id]);$old=data($record);$changes=[];foreach($fields[$k] as $key=>$label) if(($old[$key]??'')!==$d[$key]) $changes[]=$label.': '.(($old[$key]??'')!==''?$old[$key]:'(empty)').' → '.($d[$key]!==''?$d[$key]:'(empty)');$detail=$changes?'Local user changed '.implode('; ', $changes):'Local user saved the record without field changes.';}
   else {$s=$db->prepare('INSERT INTO records(kind,data) VALUES(?,?)');$s->execute([$k,$json]);$id=(int)$db->lastInsertId();$detail='Local user created the record.';}
   $s=$db->prepare('INSERT INTO events(record_id,type,detail) VALUES(?,?,?)');$s->execute([$id,'Record',$detail]);
  } elseif($action==='event') {
   $type=trim($_POST['event_type'] ?? '');$detail=trim($_POST['detail'] ?? '');
   $allowed=$k==='assets'?['Assignment','Return','Transfer','Repair','Audit']:($k==='supplies'?['Receive','Issue','Adjustment']:['Assignment','Renewal','Note']);
   if(!in_array($type,$allowed,true) || $detail==='') throw new Exception('Choose an event and enter details.');
   $db->beginTransaction();
   if($k==='supplies') { $amount=filter_var($_POST['amount'] ?? '',FILTER_VALIDATE_INT); if($amount===false || $amount<=0) throw new Exception('Enter a positive whole quantity.');$d=data($record);$before=(int)($d['quantity'] ?: 0);$after=$type==='Receive'?$before+$amount:($type==='Issue'?$before-$amount:$amount);if($after<0) throw new Exception('Not enough stock for this issue.');$d['quantity']=(string)$after;$s=$db->prepare('UPDATE records SET data=?,updated_at=CURRENT_TIMESTAMP WHERE id=?');$s->execute([json_encode($d),$id]);$detail.=" (quantity: $before → $after)"; }
   $s=$db->prepare('INSERT INTO events(record_id,type,detail) VALUES(?,?,?)');$s->execute([$id,$type,$detail]);$db->commit();
  }
  $_SESSION['flash']=$action==='event'?'Activity saved successfully.':'Record saved successfully.';header('Location: ?page='.$k.'&view='.$id);exit;
 } catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();$kind=$_POST['kind'] ?? $kind;if(!isset($fields[$kind]))$kind='dashboard';if(($_POST['action']??'')==='restore'){$kind='dashboard';$_GET['deleted']=1;}}
}
$records=[];foreach($fields as $k=>$v)$records[$k]=all($db,$k);
$view=null;$edit=null;$vid=(int)($_GET['view'] ?? 0);$eid=(int)($_GET['edit'] ?? 0);if(isset($records[$kind]))foreach($records[$kind] as $r){if((int)$r['id']===$vid)$view=$r;if((int)$r['id']===$eid)$edit=$r;}
if(isset($_GET['deleted']) && $user['role']!=='superadmin'){http_response_code(403);exit('Super administrator access required.');}
$deleted=$db->query("SELECT * FROM records WHERE deleted_at IS NOT NULL ORDER BY deleted_at DESC")->fetchAll(PDO::FETCH_ASSOC);
$recent=$db->query("SELECT e.*,r.kind,r.data,r.deleted_at FROM events e JOIN records r ON r.id=e.record_id ORDER BY e.id DESC LIMIT 5")->fetchAll(PDO::FETCH_ASSOC);
$events=[];if($view){$s=$db->prepare('SELECT * FROM events WHERE record_id=? ORDER BY id DESC');$s->execute([$view['id']]);$events=$s->fetchAll(PDO::FETCH_ASSOC);}
$alerts=[];$sites=[];$statusCounts=['In use'=>0,'In storage'=>0,'Under repair'=>0,'Retired'=>0,'Lost'=>0];$seatsTotal=0;$seatsAssigned=0;$renewals=0;$lowCount=0;
$audit=$db->prepare("SELECT MAX(created_at) FROM events WHERE record_id=? AND type='Audit'");
foreach($records['assets'] as $r){$d=data($r);$site=trim($d['site']??'');$siteKey=$site!==''?$site:'Unspecified';$status=$d['status']??'';if(isset($statusCounts[$status]))$statusCounts[$status]++;if(!isset($sites[$siteKey]))$sites[$siteKey]=['count'=>0,'statuses'=>[],'audit'=>0,'filter'=>$site];$sites[$siteKey]['count']++;$sites[$siteKey]['statuses'][$status?:'Unspecified']=($sites[$siteKey]['statuses'][$status?:'Unspecified']??0)+1;$audit->execute([$r['id']]);$last=$audit->fetchColumn();if(!$last || substr($last,0,10)<=date('Y-m-d',strtotime('-6 months'))){$sites[$siteKey]['audit']++;$alerts[]=['type'=>'Audit','kind'=>'assets','id'=>$r['id'],'name'=>$d['name'],'ref'=>$d['asset_id']??'','site'=>$siteKey,'info'=>'Last audit: '.($last?substr($last,0,10):'Never'),'badge'=>'Audit due'];}if(!empty($d['warranty']) && $d['warranty']<=date('Y-m-d',strtotime('+90 days')))$alerts[]=['type'=>'Warranty','kind'=>'assets','id'=>$r['id'],'name'=>$d['name'],'ref'=>$d['asset_id']??'','site'=>$siteKey,'info'=>'Warranty: '.$d['warranty'],'badge'=>$d['warranty']<date('Y-m-d')?'Overdue':'Due soon'];}
foreach($records['licenses'] as $r){$d=data($r);$seatsTotal+=(int)($d['seats']??0);$seatsAssigned+=(int)($d['assigned']??0);if(!empty($d['renewal']) && $d['renewal']<=date('Y-m-d',strtotime('+90 days'))){$renewals++;$alerts[]=['type'=>'Renewal','kind'=>'licenses','id'=>$r['id'],'name'=>$d['name'],'ref'=>$d['provider']??'','site'=>$d['location']?:'No location','info'=>'Renewal: '.$d['renewal'],'badge'=>$d['renewal']<date('Y-m-d')?'Overdue':'Due soon'];}}
foreach($records['supplies'] as $r){$d=data($r);if(($d['reorder']??'')!=='' && (float)($d['quantity']??0)<=(float)$d['reorder']){$lowCount++;$alerts[]=['type'=>'Low stock','kind'=>'supplies','id'=>$r['id'],'name'=>$d['name'],'ref'=>$d['sku']??'','site'=>$d['location']?:'No location','info'=>($d['quantity']?:'0').' on hand · reorder at '.$d['reorder'],'badge'=>'Low stock'];}}
$activityPage=max(1,(int)($_GET['activity_page']??1));$activityTotal=(int)$db->query('SELECT COUNT(*) FROM events')->fetchColumn();$activityPages=max(1,(int)ceil($activityTotal/20));$activityPage=min($activityPage,$activityPages);if(isset($_GET['activity'])){$q=$db->prepare('SELECT e.*,r.kind,r.data,r.deleted_at FROM events e JOIN records r ON r.id=e.record_id ORDER BY e.id DESC LIMIT 20 OFFSET ?');$q->bindValue(1,($activityPage-1)*20,PDO::PARAM_INT);$q->execute();$recent=$q->fetchAll(PDO::FETCH_ASSOC);}

?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Inventory Management System | Local prototype</title><link rel="stylesheet" href="frontend/style.css"></head><body><aside class="sidebar"><a class="brand" href="?"> <span class="brandmark">✳</span><span>INVENTORY<small>MANAGEMENT SYSTEM</small></span></a><div class="navlabel">WORKSPACE</div><nav><?php foreach(['dashboard'=>'Overview','assets'=>'Assets','supplies'=>'Supplies','licenses'=>'Licenses'] as $key=>$label):?><a class="<?= $kind===$key?'active':'' ?>" href="?page=<?= $key ?>"><span class="navicon"><?= ['dashboard'=>'◫','assets'=>'▣','supplies'=>'▤','licenses'=>'◇'][$key] ?></span><?= $label ?></a><?php endforeach;?></nav><?php if($user['role']==='superadmin'):?><a class="trashlink" href="?page=dashboard&amp;deleted=1">Deleted records</a><a class="trashlink" href="authentication/accounts.php">Account management</a><?php endif;?><div class="theme-control"><span>Dark mode</span><label class="switch"><input id="theme-toggle" type="checkbox" aria-label="Toggle dark mode"><span></span></label></div><div class="sidefoot"><span class="dot"></span> <?=h($user['display_name'])?><small><?=h($user['role'])?></small><button type="button" class="logout-button" id="logout-open">Log out</button></div></aside><dialog id="logout-dialog" class="report-dialog" aria-labelledby="logout-title"><h2 id="logout-title">Log out?</h2><p class="muted">Are you sure you want to log out?</p><form method="post" action="authentication/logout.php" class="dialog-actions"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><button class="button primary">Log out</button><button type="button" class="button secondary" id="logout-cancel">Cancel</button></form></dialog><main class="<?= $kind!=='dashboard' && !$view && !$edit && !isset($_GET['new']) ? 'register-page' : '' ?>"><?php if($kind==='dashboard'): $hour=(int)date('G');$greeting=$hour<12?'Good morning':($hour<18?'Good afternoon':'Good evening');?><header class="top dashboard-header"><h1 id="dashboard-greeting" data-user="<?=h($_SESSION['display_name']??'Local user')?>"><?=h($greeting)?>, <?=h($_SESSION['display_name']??'Local user')?></h1><div class="dashboard-clock"><span id="dashboard-date"><?=h(date('l, F j, Y'))?></span><strong id="dashboard-time"><?=h(date('g:i:s A'))?> PHT</strong></div></header><?php endif;?>
<?php if($error):?><div class="notice error"><?=h($error)?></div><?php elseif(!empty($_SESSION['flash'])):?><div class="notice" role="status"><?=h($_SESSION['flash'])?></div><?php unset($_SESSION['flash']); ?><?php endif;?>
<?php if($kind==='dashboard' && isset($_GET['activity'])):?><section class="panel"><div class="panelhead"><h2>Activity history</h2><a class="button secondary" href="?page=dashboard">← Back to dashboard</a></div><?php if(!$recent):?><div class="empty">No activity yet.</div><?php endif;?><?php foreach($recent as $activity):$ad=data($activity);?><div class="event"><strong><?=h($activity['type'])?> · <?php if(!$activity['deleted_at']):?><a class="textlink" href="?page=<?=h($activity['kind'])?>&amp;view=<?=$activity['record_id']?>"><?=h($ad['name']??'Record')?></a><?php else:?><?=h($ad['name']??'Record')?> (deleted)<?php endif;?> <small>· <?=h(ucfirst($activity['kind']))?> · <?=h($ad['asset_id']??$ad['sku']??$ad['provider']??'')?></small></strong><span><?=h($activity['detail'])?></span><small>Local user · <?=h($activity['created_at'])?> UTC</small></div><?php endforeach;?><div class="pagination"><span>Page <?=$activityPage?> of <?=$activityPages?> · <?=$activityTotal?> events</span><div><?php if($activityPage>1):?><a class="button secondary" href="?page=dashboard&amp;activity=1&amp;activity_page=<?=$activityPage-1?>">Previous</a><?php endif;?><?php if($activityPage<$activityPages):?><a class="button secondary" href="?page=dashboard&amp;activity=1&amp;activity_page=<?=$activityPage+1?>">Next</a><?php endif;?></div></div></section><?php elseif($kind==='dashboard' && isset($_GET['report'])):?><section class="panel"><div class="panelhead"><h2>Activity report</h2><a class="button secondary" href="?page=dashboard">← Back to dashboard</a></div><p class="muted">Export recorded activity within an inclusive date range. Dates use Philippine time. Deleted records and deletion events are excluded.</p><form action="backend/report.php" method="get" class="reportform"><label>Start date<input type="date" name="start" required></label><label>End date<input type="date" name="end" required></label><label>Register<select name="kind"><option value="all">All registers</option><option value="assets">Assets</option><option value="supplies">Supplies</option><option value="licenses">Licenses &amp; subscriptions</option></select></label><button class="button primary">Download CSV report</button></form></section><?php elseif($kind==='dashboard' && isset($_GET['deleted'])):?><section class="panel"><div class="panelhead"><h2>Deleted records</h2><a class="button secondary" href="?page=dashboard">← Back to dashboard</a></div><p class="muted">Records are retained locally and can be restored. Permissions will be added later.</p><?php if(!$deleted):?><div class="empty">No deleted records.</div><?php endif;?><?php foreach($deleted as $item):$dd=data($item);?><div class="attention"><div><strong><?=h($dd['name']??'Record')?></strong><small><?=h(ucfirst($item['kind']))?> · Deleted <?=h($item['deleted_at'])?> UTC</small></div><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="kind" value="<?=h($item['kind'])?>"><input type="hidden" name="id" value="<?=$item['id']?>"><input type="hidden" name="action" value="restore"><button class="button secondary">Restore</button></form></div><?php endforeach;?></section><?php elseif($kind==='dashboard'):?><div class="metrics"><a href="?page=assets" class="metric"><span class="metricicon">▣</span><span>Total assets</span><strong><?=count($records['assets'])?></strong><small>Equipment in the register →</small></a><a href="?page=supplies" class="metric"><span class="metricicon">▤</span><span>Supply items</span><strong><?=count($records['supplies'])?></strong><small>Item and location records →</small></a><a href="?page=licenses" class="metric"><span class="metricicon">◇</span><span>Subscriptions</span><strong><?=count($records['licenses'])?></strong><small>Licenses being tracked →</small></a><div class="metric alertmetric"><span class="metricicon">!</span><span>Need attention</span><strong><?=count($alerts)?></strong><small>Due dates, audits and low stock</small></div></div><div class="dashboardgrid"><section class="panel"><div class="panelhead"><div><div class="eyebrow">STAY AHEAD</div><h2>Attention needed</h2></div><span class="count"><?=count($alerts)?></span></div><p class="muted">Open an item to act on it. Dates include overdue items and those due within 90 days.</p><label class="alert-filter">Show <select id="alert-filter"><option value="">All alerts</option><?php foreach(['Audit','Warranty','Low stock','Renewal'] as $type):?><option><?=h($type)?></option><?php endforeach;?></select></label><div id="alert-list"><?php foreach($alerts as $item):?><a class="attention" data-alert-type="<?=h($item['type'])?>" href="?page=<?=h($item['kind'])?>&amp;view=<?=$item['id']?>"><span class="attentionicon">!</span><div><strong><?=h($item['name'])?></strong><small><?=h($item['ref'])?> · <?=h($item['site'])?> · <?=h($item['info'])?></small></div><span class="badge amber"><?=h($item['badge'])?></span></a><?php endforeach;?></div><p id="alert-empty" class="muted" hidden>No alerts in this category.</p><button type="button" id="more-alerts" class="button secondary" hidden>Show more</button></section><section class="panel"><div class="panelhead"><div><div class="eyebrow">ASSET DISTRIBUTION</div><h2>Assets by site</h2></div></div><p class="muted">Select a site to open its asset register.</p><?php if(!$sites):?><div class="empty">No sites yet.</div><?php endif;?><?php ksort($sites);foreach($sites as $site=>$summary):?><a class="site site-link" href="?page=assets&amp;location=<?=urlencode($summary['filter']!==''?$summary['filter']:'__unassigned__')?>"><div><strong><?=h($site)?></strong><span><?=$summary['count']?> assets</span></div><small><?php foreach($summary['statuses'] as $label=>$count):?><?=h($label)?>: <?=$count?> &nbsp; <?php endforeach;?>· Audits due: <?=$summary['audit']?></small><div class="bar"><i style="width:<?=count($records['assets'])?round($summary['count']/count($records['assets'])*100):0?>%"></i></div></a><?php endforeach;?></section></div><section class="panel"><div class="eyebrow">SUPPLIES &amp; LICENSES</div><h2>Operational summary</h2><div class="statusgrid"><div><span>Low stock records</span><strong><?=$lowCount?></strong></div><div><span>Renewals due / overdue</span><strong><?=$renewals?></strong></div><div><span>Seats assigned</span><strong><?=$seatsAssigned?></strong></div><div><span>Seats available</span><strong><?=max(0,$seatsTotal-$seatsAssigned)?></strong></div><div><span>Total seats recorded</span><strong><?=$seatsTotal?></strong></div></div></section><section class="panel statuspanel"><div class="eyebrow">ASSET STATUS</div><h2>Equipment at a glance</h2><div class="statusgrid"><?php foreach($statusCounts as $label=>$count):?><div><span><?=h($label)?></span><strong><?=$count?></strong></div><?php endforeach;?></div></section><section class="panel"><div class="panelhead"><div><div class="eyebrow">LATEST CHANGES</div><h2>Recent activity</h2></div><div><a class="button secondary" href="?page=dashboard&amp;activity=1">View all activity</a></div></div><?php if(!$recent):?><div class="empty">No activity yet.</div><?php endif;?><?php foreach($recent as $activity): $ad=data($activity);?><div class="event"><strong><?=h($activity['type'])?> · <?php if(!$activity['deleted_at']):?><a class="textlink" href="?page=<?=h($activity['kind'])?>&amp;view=<?=$activity['record_id']?>"><?=h($ad['name']??'Record')?></a><?php else:?><?=h($ad['name']??'Record')?><?php endif;?> <small>(<?=h(ucfirst($activity['kind']))?><?= $activity['deleted_at']?' · deleted':'' ?>)</small></strong><span><?=h($activity['detail'])?></span><small>Local user · <?=h($activity['created_at'])?> UTC</small></div><?php endforeach;?></section>
<?php else: ?>
<?php if(isset($_GET['new']) || $edit || ($error && ($_POST['action']??'')==='save')): $d=$error?$_POST:($edit?data($edit):[]);?><section class="panel formpanel"><div class="panelhead"><div><div class="eyebrow">REGISTER DETAILS</div><h2><?= $edit?'Edit record':'Add a record' ?></h2></div><a class="button secondary" href="?page=<?=$kind?>">← Back to register</a></div><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="kind" value="<?=$kind?>"><input type="hidden" name="id" value="<?=h($edit['id']??($_POST['id']??''))?>"><div class="formgrid"><?php foreach($fields[$kind] as $key=>$label): $required=in_array($key,$kind==='assets'?['asset_id','name']:($kind==='supplies'?['sku','name','location']:['name','provider']));$type=in_array($key,['warranty','renewal','expiry'])?'date':(in_array($key,['quantity','reorder','unit_cost','purchase_cost','seats','assigned','cost'])?'number':'text');?><label class="<?=in_array($key,['notes','specifications','assignments'])?'wide':''?>"><?=h($label)?><?=$required?' *':''?><?php if(in_array($key,['notes','specifications','assignments'])):?><textarea name="<?=$key?>" rows="2"><?=h($d[$key]??'')?></textarea><?php elseif($key==='status' && $kind==='assets'):?><select name="status"><?php foreach(['In storage','In use','Under repair','Retired','Lost'] as $option):?><option <?=($d[$key]??'')===$option?'selected':''?>><?=h($option)?></option><?php endforeach;?></select><?php else:?><input name="<?=$key?>" type="<?=$type?>" <?= $type==='number'?'min="0" step="'.(in_array($key,['unit_cost','purchase_cost','cost'])?'0.01':'1').'"':'' ?> <?=$required?'required':''?> value="<?=h($d[$key]??'')?>"><?php endif;?></label><?php endforeach;?></div><div class="formactions"><button class="button primary">Save record</button><a class="button secondary" href="?page=<?=$kind?>">Cancel</a></div></form></section><?php endif;?>
<?php if($view):$d=data($view);?><section class="panel detail"><div class="panelhead"><div><div class="eyebrow">RECORD DETAILS</div><h2><?=h($d['name']??'Record')?></h2></div><div class="detailactions"><button type="button" class="button secondary" id="download-details">Download image</button><a class="button secondary" href="?page=<?=$kind?>&edit=<?=$view['id']?>">Edit record</a> <?php if($user['role']==='superadmin'):?><form method="post" onsubmit="return confirm('Move this record to deleted records?')"><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="kind" value="<?=$kind?>"><input type="hidden" name="id" value="<?=$view['id']?>"><input type="hidden" name="action" value="delete"><button class="button danger" type="submit">Delete</button></form><?php endif;?> <a class="button secondary" href="?page=<?=$kind?>">← Back to register</a></div></div><div class="detailgrid"><?php foreach($fields[$kind] as $key=>$label):?><div><small><?=h($label)?></small><strong><?=h($d[$key]!==''?$d[$key]:'—')?></strong></div><?php endforeach;?></div><div class="history"><div><div class="eyebrow">ACTIVITY</div><h2>History</h2><p class="muted">Events are recorded with a timestamp.</p><?php foreach($events as $event):?><div class="event"><strong><?=h($event['type'])?></strong><span><?=h($event['detail'])?></span><small><?=h($event['created_at'])?> UTC</small></div><?php endforeach;?></div><details class="activity-entry"><summary class="button secondary">＋ Record activity</summary><form method="post" class="eventform"><h3>Record activity</h3><input type="hidden" name="csrf" value="<?=h($_SESSION['csrf'])?>"><input type="hidden" name="kind" value="<?=$kind?>"><input type="hidden" name="id" value="<?=$view['id']?>"><input type="hidden" name="action" value="event"><label>Activity<select name="event_type"><?php foreach($kind==='assets'?['Assignment','Return','Transfer','Repair','Audit']:($kind==='supplies'?['Receive','Issue','Adjustment']:['Assignment','Renewal','Note']) as $option):?><option><?=h($option)?></option><?php endforeach;?></select></label><?php if($kind==='supplies'):?><label>Quantity <small>(adjustment sets the new quantity)</small><input name="amount" type="number" min="1" step="1" required></label><?php endif;?><label>Details<textarea name="detail" rows="3" required placeholder="Add context for this activity"></textarea></label><button class="button primary">Add activity</button><p class="muted">For assets and licenses, activity is a history note. Edit the record to update its current details.</p></form></details></div></section><?php endif;?>
<?php if(!$view && !$edit && !isset($_GET['new']) && !$error):?><section class="panel register"><div class="panelhead"><div><div class="eyebrow">ALL RECORDS</div><h2><?=$kind==='licenses'?'Licenses &amp; subscriptions':h(ucfirst($kind))?> <span class="count"><?=count($records[$kind])?></span></h2></div><div class="toolbar"><input id="search" type="search" placeholder="Search all fields…" aria-label="Search records"><select id="filter" aria-label="Filter records"><option value="">All <?= $kind==='assets'?'statuses':($kind==='supplies'?'locations':'providers') ?></option><?php $filterkey=$kind==='assets'?'status':($kind==='supplies'?'location':'provider');$opts=[];foreach($records[$kind] as $r){$v=data($r)[$filterkey]??'';if($v!=='')$opts[$v]=true;}ksort($opts);foreach(array_keys($opts) as $opt):?><option><?=h($opt)?></option><?php endforeach;?></select><?php if($kind!=='supplies'): $locationKey=$kind==='assets'?'site':'location';$locations=[];foreach($records[$kind] as $r){$loc=data($r)[$locationKey]??'';if($loc!=='')$locations[$loc]=true;}ksort($locations);?><select id="location-filter" aria-label="Filter by location"><option value="">All locations</option><?php foreach(array_keys($locations) as $loc):?><option><?=h($loc)?></option><?php endforeach;?><option value="__unassigned__">No location specified</option></select><?php endif;?><button type="button" class="button secondary" id="open-report">Export Data</button><a class="button primary" href="?page=<?=$kind?>&amp;new=1">＋ &nbsp; Add <?= ['assets'=>'asset','supplies'=>'supply','licenses'=>'license'][$kind] ?></a></div></div><div class="tablewrap"><table><thead><tr><th><button type="button" class="sort-date" id="sort-created" aria-label="Sort by date created, newest first" aria-pressed="false"><span id="sort-arrow" aria-hidden="true">↓</span> Date Created</button></th><?php $columns=$kind==='assets'?['asset_id','name','category','employee','site','status','purchase_cost','warranty']:($kind==='supplies'?['sku','name','location','quantity','reorder','unit_cost','supplier']:['name','provider','location','seats','assigned','cost','frequency','renewal','expiry']);foreach($columns as $col):?><th><?=h($fields[$kind][$col])?></th><?php endforeach;?><th></th></tr></thead><tbody><?php foreach($records[$kind] as $r):$d=data($r);?><tr data-search="<?=h(strtolower(implode(' ',array_values($d))))?>" data-filter="<?=h($d[$filterkey]??'')?>" data-location="<?=h($d[$kind==='assets'?'site':'location']??'')?>" data-created="<?=h($r['created_at'])?>" data-id="<?=$r['id']?>"><td><?=h((new DateTimeImmutable($r['created_at'],new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Asia/Manila'))->format('Y-m-d H:i'))?></td><?php foreach($columns as $col):?><td><?=h($d[$col]!==''?(in_array($col,['purchase_cost','unit_cost','cost'],true)?money($d[$col]):$d[$col]):'—')?></td><?php endforeach;?><td><a class="button secondary" href="?page=<?=$kind?>&view=<?=$r['id']?>">View</a></td></tr><?php endforeach;?></tbody></table><?php if(!$records[$kind]):?><div class="empty">No records yet.<small>Use the button above to add your first record.</small></div><?php endif;?><div id="no-results" class="empty" hidden>No matching records.<small>Try a different search or filter.</small></div></div><div class="pagination" id="pagination" hidden><span id="page-summary" aria-live="polite"></span><div><label for="page-size">Rows per page</label> <select id="page-size"><option selected>13</option><option>20</option><option>50</option></select> <button type="button" class="button secondary" id="prev-page">Previous</button> <button type="button" class="button secondary" id="next-page">Next</button></div></div></section><dialog id="report-dialog" class="report-dialog" aria-labelledby="report-title"><div class="panelhead"><div><div class="eyebrow">REGISTER EXPORT</div><h2 id="report-title">Export data</h2></div><button type="button" class="button secondary" id="close-report" aria-label="Close date report">✕</button></div><p class="muted">Export records added during an inclusive date range, or export all active records. Dates use Philippine time.</p><form action="backend/export.php" method="get" class="dialog-form"><input type="hidden" name="kind" value="<?=h($kind)?>"><p class="muted">The export contains current record details and can be opened in Excel.</p><label>Start date<input type="date" name="start" required value="<?=h(date('Y-m-01'))?>"></label><label>End date<input type="date" name="end" required value="<?=h(date('Y-m-d'))?>"></label><div class="dialog-actions"><button type="submit" class="button primary">Export date range</button><a class="button secondary" href="backend/export.php?kind=<?=h($kind)?>">Export all CSV</a><button type="button" class="button secondary" id="cancel-report">Cancel</button></div></form></dialog><?php endif;?><?php endif;?></main><script src="frontend/app.js"></script></body></html>
